package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.util.*;
@Controller public class AdminOperationsController {
 private final UserAccountRepository users;private final RideBookingRepository rides;private final VehicleRepository vehicles;private final PaymentRecordRepository payments;private final SupportTicketRepository tickets;private final SafetyReportRepository safety;private final RideReviewRepository reviews;
 public AdminOperationsController(UserAccountRepository u,RideBookingRepository r,VehicleRepository v,PaymentRecordRepository p,SupportTicketRepository t,SafetyReportRepository s,RideReviewRepository rv){users=u;rides=r;vehicles=v;payments=p;tickets=t;safety=s;reviews=rv;}
 @GetMapping("/admin/operations") public String dashboard(Model m){List<RideBooking> all=rides.findAll();List<PaymentRecord> ps=payments.findAll();m.addAttribute("customers",users.findByRoleIn(List.of("CUSTOMER")).size());m.addAttribute("partners",users.findByRoleIn(List.of("DRIVER","FLEET_OWNER")).size());m.addAttribute("vehicles",vehicles.count());m.addAttribute("totalRides",all.size());m.addAttribute("activeRides",all.stream().filter(r->List.of("REQUESTED","ACCEPTED","ASSIGNED","IN_PROGRESS").contains(r.getStatus())).count());m.addAttribute("completedRides",all.stream().filter(r->"COMPLETED".equals(r.getStatus())).count());m.addAttribute("cancelledRides",all.stream().filter(r->"CANCELLED".equals(r.getStatus())).count());m.addAttribute("grossPaid",ps.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(PaymentRecord::getGrossAmount).sum());m.addAttribute("commission",ps.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(PaymentRecord::getCommissionAmount).sum());m.addAttribute("openTickets",tickets.findAll().stream().filter(t->!List.of("RESOLVED","CLOSED").contains(t.getStatus())).count());m.addAttribute("openSafety",safety.findAll().stream().filter(s->!List.of("RESOLVED","CLOSED").contains(s.getStatus())).count());return "admin-operations";}
 @GetMapping("/admin/users") public String users(Model m){m.addAttribute("users",users.findAll());return "admin-users";}
 @PostMapping("/admin/users/{id}/status") public String userStatus(@PathVariable String id,@RequestParam String status){UserAccount u=users.findById(id).orElseThrow();if("ADMIN".equals(u.getRole())||!List.of("APPROVED","PENDING","REJECTED","SUSPENDED").contains(status))return "redirect:/admin/users?error";u.setStatus(status);if("SUSPENDED".equals(status))u.setAvailable(false);users.save(u);return "redirect:/admin/users?updated";}
 @GetMapping("/admin/safety") public String safety(Model m){m.addAttribute("reports",safety.findAllByOrderByCreatedAtDesc());return "admin-safety";}
 @GetMapping("/admin/reviews") public String reviews(Model m){m.addAttribute("reviews",reviews.findAllByOrderByCreatedAtDesc());return "admin-reviews";}
}
